---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Stat cards: Four headline numbers with sparklines and a period switch.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change stat-cards.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './stat-cards.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="stat-cards" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="scx">
  <div class="scx-h"><div class="seg2 scx-sg" role="group" aria-label="Period"><button aria-pressed="false" data-v="0">7 days</button><button aria-pressed="true" data-v="1">30 days</button><button aria-pressed="false" data-v="2">Quarter</button></div></div>
  <div class="scx-grid"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './stat-cards.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Stat cards ---------- */
/* a row of headline numbers, each with its change against the period before and a sparkline in the chart palette. The cards
   aren't buttons, so a pointer over them changes nothing; the change chip says what it is measured against when you point
   at it */
.scx{display:flex;flex-direction:column;gap:10px;width:100%}
.scx-h{display:flex;justify-content:flex-end}
.scx-sg button{font-size:12px;height:26px;padding:0 10px}
.scx-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:820px){.scx-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* phones keep two columns, two rows, with the cards' 16px insets, and the change chip goes under the number when it can't fit
   beside it */
@media (max-width:520px){.scx-grid{gap:var(--dm-s-2)}.scx-v{flex-wrap:wrap;row-gap:var(--dm-s-1)}.scx-sp{height:28px}}
.scx-c{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:6px;min-width:0}
.scx-k{display:flex;align-items:center;gap:6px;font-size:12.5px;line-height:18px;color:var(--dm-muted)}
.scx-k .ic{display:grid;color:var(--dm-fg2)}
.scx-v{display:flex;align-items:center;gap:var(--dm-s-2)}
.scx-v b{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.02em}
.scx-d{font-size:12px;font-weight:500}
.scx-d.tag{display:inline-flex;height:20px;padding:0 6px;cursor:default}
.scx-sr{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.scx-sp{height:34px;margin-top:var(--dm-s-1)}
.scx-sp svg{width:100%;height:100%;overflow:visible}
.scx-sp path{fill:none;stroke-width:1.75;vector-effect:non-scaling-stroke;stroke-linejoin:round;transition:d .8s var(--dm-ease)}
/* the area under a line, which only Clean draws */
.scx-sp path.ar{display:none;stroke:none}
/* Clean (owner, 17 and 18 Nov): each card's content 16px in from every edge */
:root[data-style="clean"] .scx-c.panel,:root [data-style="clean"] .scx-c.panel,:root [data-style="clean"].scx-c.panel{padding:16px}
/* Clean (owner, 21 Nov: "design something custom because apart from the switcher and the shape of the containers there's no
   difference between Soft and Clean"): one panel instead of four cards. The period switch sits in its off-white head strip
   under a hairline; under it the figures are cells of one grid, split by half-strength hairlines (the grid's 1px gaps), each
   with its label, figure and change chip (a status chip) on the same lines as its neighbours', 16px in. The sparklines keep
   the chart palette, as Soft's do (the first in the accent, white in dark through its token, then --dm-c2 to --dm-c4): thin lines
   with straight segments and sharp corners, the area under each fading from its line's colour to nothing */
:root[data-style="clean"] .scx,:root [data-style="clean"] .scx,:root [data-style="clean"].scx{gap:0;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:hidden}
:root[data-style="clean"] .scx-h,:root [data-style="clean"] .scx-h,:root [data-style="clean"].scx-h{align-items:center;min-height:48px;padding:8px 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line)}
:root[data-style="clean"] .scx>.scx-grid,:root [data-style="clean"] .scx>.scx-grid,:root [data-style="clean"].scx>.scx-grid{gap:1px;background:color-mix(in srgb,var(--dm-line) 50%,var(--dm-surface))}
:root[data-style="clean"] .scx>.scx-grid>.scx-c.panel,:root [data-style="clean"] .scx>.scx-grid>.scx-c.panel,:root [data-style="clean"].scx>.scx-grid>.scx-c.panel{background:var(--dm-surface);border-radius:0;box-shadow:none}
:root[data-style="clean"] .scx-sp path.ln,:root [data-style="clean"] .scx-sp path.ln,:root [data-style="clean"].scx-sp path.ln{stroke-width:1.25;stroke-linejoin:miter}
:root[data-style="clean"] .scx-sp path.ar,:root [data-style="clean"] .scx-sp path.ar,:root [data-style="clean"].scx-sp path.ar{display:inline}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, seg, stagger, swap, tween } from '../core/core.js';
DM.def('stat-cards', (r, c) => {
  // icon, label, [value, change %] for each period, unit, the sparkline's shape, and whether lower is better: spend falling is
  // good news, so its chip is green when it falls and red when it rises
  const S = [
    ['spark','Agent runs',[[412,12],[1730,18],[4980,22]],'',[3,4,4,5,6,5,7,8]],
    ['users','Active editors',[[318,4],[1130,9],[1620,31]],'',[5,5,6,6,6,7,7,8]],
    ['clock','Hours saved',[[96,15],[402,21],[1180,26]],'h',[2,3,3,4,5,6,6,8]],
    ['coins','Agent spend',[[84,-6],[341,-3],[960,8]],'$',[6,5,6,5,4,4,4,3],true]
  ];
  const CMP = ['vs previous 7 days','vs previous 30 days','vs last quarter'];
  const grid = $('.scx-grid', r), uid = Math.random().toString(36).slice(2, 7); let per = 1;
  // each sparkline is its line and, under it, the area down to the axis, which Clean fills with the line's colour fading to nothing
  grid.innerHTML = S.map((s, i) => `<div class="scx-c panel"><span class="scx-k"><span class="ic">${I(s[0],'xs')}</span>${s[1]}</span><div class="scx-v"><b class="num">0</b><span class="scx-d num"></span><span class="scx-sr"></span></div><div class="scx-sp"><svg viewBox="0 0 100 30" preserveAspectRatio="none" style="color:var(--dm-c${i + 1})"><defs><linearGradient id="scx-${uid}-${i}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".22"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><path class="ar" style="fill:url(#scx-${uid}-${i})" d="M0 30 L100 30 Z"/><path class="ln" stroke="var(--dm-c${i + 1})" d="M0 30 L100 30"/></svg></div></div>`).join('');
  const cards = $$('.scx-c', grid), cur = S.map(() => 0);
  const fmt = (s, v) => s[3] === '$' ? '$' + Math.round(v).toLocaleString('en-US') : Math.round(v).toLocaleString('en-US') + s[3];
  function draw(p){
    per = p; cards.forEach((el, i) => { const s = S[i], [val, ch] = s[2][p];
      tween(cur[i], val, 900, v => { cur[i] = v; $('b', el).textContent = fmt(s, v); });
      // the chip: green when the change is good news, red when it isn't, with a true minus sign; pointing at it says what it
      // is measured against, and screen readers hear it after the number
      const good = s[5] ? ch <= 0 : ch >= 0, txt = (ch > 0 ? '+' : ch < 0 ? '\u2212' : '') + Math.abs(ch) + '%';
      const d = $('.scx-d', el); d.className = 'tag scx-d num ' + (good ? 'ok' : 'bad') + (ch >= 0 ? ' up' : ' dn'); swap(d, txt); d.dataset.tip = CMP[p];
      $('.scx-sr', el).textContent = CMP[p];
      const pts = s[4].map((y, k) => { const yy = y + Math.sin(k * 1.7 + p * 2) * (p ? 1 : .5); return `${k === 0 ? 'M' : 'L'}${(k / 7 * 100).toFixed(1)} ${(29 - yy * 3.2).toFixed(1)}`; }).join(' ');
      $('path.ln', el).setAttribute('d', pts); $('path.ar', el).setAttribute('d', pts + ' L100 30 L0 30 Z'); });
  }
  seg($('.scx-sg', r), v => draw(+v));
  stagger(cards, 70);
  c.later(240, () => draw(1));
  if (!REDUCE) cards.forEach((el, i) => $('.scx-sp svg', el).animate([{ clipPath:'inset(-4px 100% -4px 0)' }, { clipPath:'inset(-4px 0% -4px 0)' }], { duration:1000, delay:300 + i * 70, easing:'cubic-bezier(.45,0,.2,1)', fill:'backwards' }));
});
